dtsPropsFor.Button:
/** `default` : une touche biseautée au trait discret. `primary` : la confirmation, le seul bouton plein — d'os, texte couleur du vide. `danger` : le geste destructeur, teinte des refus. `ghost` : sans cadre, pour « Annuler ». */
  variant?: "default" | "primary" | "danger" | "ghost";
  size?: "sm" | "md";
  /** Une icône avant le libellé. */
  icon?: "eye" | "eyeOff" | "check" | "user" | "userPlus" | "message" | "link" | "mail" | "shield" | "ban" | "unban" | "impersonate" | "logout" | "trash" | "key" | "pencil" | "plus" | "close" | "search" | "copy" | "previous" | "next" | "first" | "last" | "play" | "pause" | "rotateLeft" | "rotateRight" | "cube";
  type?: "button" | "submit" | "reset";
  /** Attribut transmis au <button>. */
  disabled?: boolean;
  /** Écouteur transmis au <button> (`@click`). */
  onClick?: (event: MouseEvent) => void;
  title?: string;
  /** Emplacement par défaut : le libellé. */

dtsPropsFor.IconButton:
icon: "eye" | "eyeOff" | "check" | "user" | "userPlus" | "message" | "link" | "mail" | "shield" | "ban" | "unban" | "impersonate" | "logout" | "trash" | "key" | "pencil" | "plus" | "close" | "search" | "copy" | "previous" | "next" | "first" | "last" | "play" | "pause" | "rotateLeft" | "rotateRight" | "cube";
  /** Le libellé accessible, montré en infobulle au survol. Obligatoire : une icône seule ne dit rien. */
  label: string;
  /** Écouteur transmis au <button> (`@click`). */
  onClick?: (event: MouseEvent) => void;
  /** Le geste est destructeur : la teinte des refus au survol. */
  danger?: boolean;
  /** Rend le bouton inactif et remplace l'infobulle par la raison. Préférer ceci à `disabled` seul. */
  disabledReason?: string;
  disabled?: boolean;
  /** Ancre l'infobulle à droite quand le bouton touche le bord droit d'un conteneur. */
  tipAlign?: "center" | "end";
  type?: "button" | "submit";

dtsPropsFor.TextField:
/** Le libellé, au-dessus du champ, en minuscules estompées. */
  label: string;
  /** Une précision sous le champ (ou l'emplacement `hint`). */
  hint?: string;
  /** Le refus propre à ce champ, sous lui, dans la teinte des refus. */
  error?: string;
  type?: "text" | "email" | "password" | "search" | "number";
  /** La valeur, liée par `v-model`. */
  modelValue?: string;
  "onUpdate:modelValue"?: (value: string) => void;
  /** Attributs transmis au <input>. */
  placeholder?: string;
  name?: string;
  autocomplete?: string;
  required?: boolean;
  disabled?: boolean;

dtsPropsFor.SelectField:
label: string;
  options: readonly { value: string; label: string }[];
  /** La valeur, liée par `v-model`. */
  modelValue?: string;
  "onUpdate:modelValue"?: (value: string) => void;
  /** Attributs transmis au <select>. */
  name?: string;
  disabled?: boolean;

dtsPropsFor.Icon:
/** Le nom de l'icône, parmi `ICON_NAMES`. */
  name: "eye" | "eyeOff" | "check" | "user" | "userPlus" | "message" | "link" | "mail" | "shield" | "ban" | "unban" | "impersonate" | "logout" | "trash" | "key" | "pencil" | "plus" | "close" | "search" | "copy" | "previous" | "next" | "first" | "last" | "play" | "pause" | "rotateLeft" | "rotateRight" | "cube";
  /** Côté en pixels. 16 par défaut, la taille des boutons à icône. */
  size?: number;

dtsPropsFor.PasswordField:
/** Le libellé, au-dessus du champ, en minuscules estompées. */
  label: string;
  /** `current-password` pour se connecter, `new-password` pour en choisir un. */
  autocomplete: "current-password" | "new-password";
  /** Une précision sous le champ (ou l'emplacement `hint`). */
  hint?: string;
  /** Le refus propre à ce champ, sous lui, dans la teinte des refus. */
  error?: string;
  /** La valeur, liée par `v-model`. */
  modelValue?: string;
  "onUpdate:modelValue"?: (value: string) => void;
  /** Attributs transmis au <input>. */
  placeholder?: string;
  name?: string;
  required?: boolean;
  minlength?: number;
  disabled?: boolean;

